"use client"

import { useEffect, useRef, useState, type PointerEvent } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/cn"

import {
  inkAdvect,
  inkDisplay,
  inkDiverge,
  inkJacobi,
  inkProject,
  inkSplatDye,
  inkSplatVelocity,
  inkVertex,
} from "./fluid-ink-shaders"
import { mountGlLoop, type GlContext, type GlFrame, type GlLoopHandle, type GlPair, type GlTarget } from "./gl/gl-loop"

/** original implementation. Pointer and touch stir ink inside this element. */

export interface InkPoint {
  x: number
  y: number
}

export interface InkImpulse {
  x: number
  y: number
  vx: number
  vy: number
  amount: number
}

export interface FluidInkCursorProps {
  speed?: number
  intensity?: number
  colors?: readonly string[]
  className?: string
}

/** 离开指针后的墨量。seconds 为 0 时原样返回；过小则归零。 */
export function decayInk(amount: number, speed: number, seconds: number): number {
  if (!(amount > 0)) return 0
  if (!(seconds > 0)) return amount
  const kept = amount / (1 + seconds * (2 + speed))
  return kept < 0.001 ? 0 : kept
}

/** 按下是一小团墨，移动把位移乘进速度。强度为 0 时不注入。 */
export function injectPointer(
  amount: number,
  previous: InkPoint | null,
  next: InkPoint,
  speed: number,
  intensity: number,
): InkImpulse {
  const dx = previous ? next.x - previous.x : 0
  const dy = previous ? next.y - previous.y : 0
  const gain = (speed > 0 ? speed : 0) * (intensity > 0 ? intensity : 0)
  const stir = previous ? Math.min(1, Math.hypot(dx, dy) * gain) : Math.min(1, gain * 0.25)
  const base = amount > 0 ? amount : 0
  return {
    x: next.x,
    y: next.y,
    vx: dx * gain,
    vy: dy * gain,
    amount: Math.min(1, base + stir),
  }
}

function clampSpeed(speed: number) {
  if (!Number.isFinite(speed)) return 1
  return Math.min(2.5, Math.max(0.25, speed))
}

function clampIntensity(intensity: number) {
  if (!Number.isFinite(intensity)) return 0.55
  return Math.min(1, Math.max(0, intensity))
}

function parseCssColor(input: string): [number, number, number] | null {
  const text = input.trim()
  const hex = /^#([\da-f]{3}|[\da-f]{6})$/i.exec(text)
  const body = hex?.[1]
  if (body) {
    const full = body.length === 3 ? body.split("").map((char) => char + char).join("") : body
    const value = Number.parseInt(full, 16)
    return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
  }
  const rgb = /^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i.exec(text)
  if (!rgb?.[1] || !rgb[2] || !rgb[3]) return null
  return [Number(rgb[1]) / 255, Number(rgb[2]) / 255, Number(rgb[3]) / 255]
}

const TOKEN_NAMES = ["--primary", "--chart-2", "--chart-4"] as const
const TOKEN_FALLBACK: [number, number, number][] = [
  [0.2, 0.28, 0.45],
  [0.12, 0.4, 0.38],
  [0.55, 0.32, 0.16],
]

function inkAt(index: number): [number, number, number] {
  return TOKEN_FALLBACK[index] ?? TOKEN_FALLBACK[0] ?? [0.2, 0.28, 0.45]
}

function themeInkColors(style: CSSStyleDeclaration): [number, number, number][] {
  return TOKEN_NAMES.map((name, index) => parseCssColor(style.getPropertyValue(name)) ?? inkAt(index))
}

function paletteFrom(style: CSSStyleDeclaration, colors: readonly string[] | undefined) {
  if (!colors || colors.length === 0) return themeInkColors(style)
  return [0, 1, 2].map((index) => parseCssColor(colors[index] ?? "") ?? inkAt(index))
}

function backdropOf(style: CSSStyleDeclaration): [number, number, number] {
  return parseCssColor(style.backgroundColor) ?? parseCssColor(style.getPropertyValue("--background")) ?? [0.97, 0.96, 0.94]
}

function stillPaint(colors: readonly string[] | undefined) {
  const a = colors?.[0] || "var(--primary)"
  const b = colors?.[1] || "var(--chart-2)"
  const c = colors?.[2] || "var(--chart-4)"
  return [
    `radial-gradient(42% 48% at 28% 42%, color-mix(in oklab, ${a} 70%, transparent), transparent 70%)`,
    `radial-gradient(36% 42% at 72% 62%, color-mix(in oklab, ${b} 60%, transparent), transparent 72%)`,
    `radial-gradient(28% 34% at 48% 28%, color-mix(in oklab, ${c} 50%, transparent), transparent 74%)`,
  ].join(",")
}

function localPoint(host: HTMLElement, clientX: number, clientY: number): InkPoint {
  const rect = host.getBoundingClientRect()
  const width = rect.width || 1
  const height = rect.height || 1
  return {
    x: Math.min(1, Math.max(0, (clientX - rect.left) / width)),
    y: Math.min(1, Math.max(0, 1 - (clientY - rect.top) / height)),
  }
}

interface Compiled {
  program: WebGLProgram
  loc: (name: string) => WebGLUniformLocation | null
}

function shaderOf(gl: GlContext, type: number, source: string) {
  const item = gl.createShader(type)
  if (!item) return null
  gl.shaderSource(item, source)
  gl.compileShader(item)
  if (!gl.getShaderParameter(item, gl.COMPILE_STATUS)) {
    gl.deleteShader(item)
    return null
  }
  return item
}

function compile(gl: GlContext, vertex: string, fragment: string): Compiled | null {
  const program = gl.createProgram()
  if (!program) return null
  const vs = shaderOf(gl, gl.VERTEX_SHADER, vertex)
  const fs = shaderOf(gl, gl.FRAGMENT_SHADER, fragment)
  if (!vs || !fs) {
    if (vs) gl.deleteShader(vs)
    if (fs) gl.deleteShader(fs)
    gl.deleteProgram(program)
    return null
  }
  gl.attachShader(program, vs)
  gl.attachShader(program, fs)
  gl.bindAttribLocation(program, 0, "a")
  gl.linkProgram(program)
  gl.deleteShader(vs)
  gl.deleteShader(fs)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program)
    return null
  }
  return { program, loc: (name) => gl.getUniformLocation(program, name) }
}

interface Tuning {
  speed: number
  intensity: number
  colors: readonly string[] | undefined
}

interface InkSession {
  stir: (previous: InkPoint | null, next: InkPoint, speed: number, intensity: number) => void
  draw: (frame: GlFrame) => void
  dispose: () => void
}

const SIM = 128
const JACOBI = 4

function bindTex(gl: GlContext, unit: number, texture: WebGLTexture) {
  gl.activeTexture(gl.TEXTURE0 + unit)
  gl.bindTexture(gl.TEXTURE_2D, texture)
}

function begin(gl: GlContext, program: WebGLProgram, target: GlTarget) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer)
  gl.viewport(0, 0, target.width, target.height)
  gl.useProgram(program)
}

function clearTarget(gl: GlContext, target: GlTarget) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer)
  gl.viewport(0, 0, target.width, target.height)
  gl.clearColor(0, 0, 0, 0)
  gl.clear(gl.COLOR_BUFFER_BIT)
}

function startSession(loop: GlLoopHandle, host: HTMLElement, tuning: { readonly current: Tuning }): InkSession | null {
  const gl = loop.gl
  const webgl2 = typeof (gl as WebGL2RenderingContext).drawBuffers === "function"
  const vertex = inkVertex(webgl2)
  const made: Compiled[] = []
  function take(fragment: string) {
    const item = compile(gl, vertex, fragment)
    if (item) made.push(item)
    return item
  }
  const splatVel = take(inkSplatVelocity(webgl2))
  const splatDye = take(inkSplatDye(webgl2))
  const advect = take(inkAdvect(webgl2))
  const diverge = take(inkDiverge(webgl2))
  const jacobi = take(inkJacobi(webgl2))
  const project = take(inkProject(webgl2))
  const display = take(inkDisplay(webgl2))
  const programs = [splatVel, splatDye, advect, diverge, jacobi, project, display]
  const vel = loop.createPair(SIM, SIM)
  const dye = loop.createPair(SIM, SIM)
  const press = loop.createPair(SIM, SIM)
  const scratch = loop.createPair(SIM, SIM)
  const pairs = [vel, dye, press, scratch]
  if (programs.some((item) => !item) || pairs.some((item) => !item)) {
    for (const item of made) gl.deleteProgram(item.program)
    for (const pair of pairs) pair?.dispose()
    return null
  }
  const ready = {
    splatVel: splatVel as Compiled,
    splatDye: splatDye as Compiled,
    advect: advect as Compiled,
    diverge: diverge as Compiled,
    jacobi: jacobi as Compiled,
    project: project as Compiled,
    display: display as Compiled,
    vel: vel as GlPair,
    dye: dye as GlPair,
    press: press as GlPair,
    scratch: scratch as GlPair,
  }
  const splats: InkImpulse[] = []
  let ink = 0
  let colorIndex = 0
  const texel: [number, number] = [1 / SIM, 1 / SIM]

  return {
    stir(previous, next, speed, intensity) {
      const impulse = injectPointer(ink, previous, next, speed, intensity)
      const added = Math.max(0, impulse.amount - ink)
      ink = impulse.amount
      if (added <= 0 && impulse.vx === 0 && impulse.vy === 0) return
      splats.push({ ...impulse, amount: added })
      if (splats.length > 8) splats.shift()
    },
    draw(frame) {
      const speed = clampSpeed(tuning.current.speed)
      const intensity = clampIntensity(tuning.current.intensity)
      const step = Math.min(0.05, frame.dt) * speed
      const dyeKeep = decayInk(1, speed, frame.dt)
      const velKeep = decayInk(1, speed, frame.dt * 0.2)
      ink = decayInk(ink, speed, frame.dt)
      const style = getComputedStyle(host)
      const palette = paletteFrom(style, tuning.current.colors)
      const radius = 0.03 + intensity * 0.07
      gl.disable(gl.BLEND)
      const queued = splats.splice(0, splats.length)
      for (const splat of queued) {
        const color = palette[colorIndex % palette.length] ?? inkAt(0)
        colorIndex += 1
        if (splat.vx !== 0 || splat.vy !== 0) {
          const prog = ready.splatVel
          begin(gl, prog.program, ready.vel.write)
          bindTex(gl, 0, ready.vel.read.texture)
          gl.uniform1i(prog.loc("uTex"), 0)
          gl.uniform2f(prog.loc("uPoint"), splat.x, splat.y)
          gl.uniform2f(prog.loc("uForce"), splat.vx * 16, splat.vy * 16)
          gl.uniform1f(prog.loc("uRadius"), radius)
          loop.draw()
          ready.vel.swap()
        }
        if (splat.amount > 0) {
          const prog = ready.splatDye
          begin(gl, prog.program, ready.dye.write)
          bindTex(gl, 0, ready.dye.read.texture)
          gl.uniform1i(prog.loc("uTex"), 0)
          gl.uniform2f(prog.loc("uPoint"), splat.x, splat.y)
          gl.uniform3f(prog.loc("uColor"), color[0], color[1], color[2])
          gl.uniform1f(prog.loc("uAmount"), splat.amount)
          gl.uniform1f(prog.loc("uRadius"), radius)
          loop.draw()
          ready.dye.swap()
        }
      }
      const flow = ready.advect
      begin(gl, flow.program, ready.vel.write)
      bindTex(gl, 0, ready.vel.read.texture)
      bindTex(gl, 1, ready.vel.read.texture)
      gl.uniform1i(flow.loc("uTex"), 0)
      gl.uniform1i(flow.loc("uVel"), 1)
      gl.uniform1f(flow.loc("uDt"), step)
      gl.uniform1f(flow.loc("uKeep"), velKeep)
      gl.uniform1f(flow.loc("uDye"), 0)
      loop.draw()
      ready.vel.swap()
      const div = ready.diverge
      begin(gl, div.program, ready.scratch.write)
      bindTex(gl, 0, ready.vel.read.texture)
      gl.uniform1i(div.loc("uVel"), 0)
      gl.uniform2f(div.loc("uTexel"), texel[0], texel[1])
      loop.draw()
      ready.scratch.swap()
      clearTarget(gl, ready.press.read)
      clearTarget(gl, ready.press.write)
      for (let pass = 0; pass < JACOBI; pass += 1) {
        const prog = ready.jacobi
        begin(gl, prog.program, ready.press.write)
        bindTex(gl, 0, ready.press.read.texture)
        bindTex(gl, 1, ready.scratch.read.texture)
        gl.uniform1i(prog.loc("uPress"), 0)
        gl.uniform1i(prog.loc("uDiv"), 1)
        gl.uniform2f(prog.loc("uTexel"), texel[0], texel[1])
        loop.draw()
        ready.press.swap()
      }
      const grad = ready.project
      begin(gl, grad.program, ready.vel.write)
      bindTex(gl, 0, ready.vel.read.texture)
      bindTex(gl, 1, ready.press.read.texture)
      gl.uniform1i(grad.loc("uVel"), 0)
      gl.uniform1i(grad.loc("uPress"), 1)
      gl.uniform2f(grad.loc("uTexel"), texel[0], texel[1])
      loop.draw()
      ready.vel.swap()
      begin(gl, flow.program, ready.dye.write)
      bindTex(gl, 0, ready.dye.read.texture)
      bindTex(gl, 1, ready.vel.read.texture)
      gl.uniform1i(flow.loc("uTex"), 0)
      gl.uniform1i(flow.loc("uVel"), 1)
      gl.uniform1f(flow.loc("uDt"), step)
      gl.uniform1f(flow.loc("uKeep"), dyeKeep)
      gl.uniform1f(flow.loc("uDye"), 1)
      loop.draw()
      ready.dye.swap()
      const [red, green, blue] = backdropOf(style)
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      gl.viewport(0, 0, frame.size.width, frame.size.height)
      gl.clearColor(red, green, blue, 1)
      gl.clear(gl.COLOR_BUFFER_BIT)
      gl.enable(gl.BLEND)
      gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA)
      gl.useProgram(ready.display.program)
      bindTex(gl, 0, ready.dye.read.texture)
      gl.uniform1i(ready.display.loc("uTex"), 0)
      loop.draw()
      gl.disable(gl.BLEND)
    },
    dispose() {
      ready.vel.dispose()
      ready.dye.dispose()
      ready.press.dispose()
      ready.scratch.dispose()
      for (const item of made) gl.deleteProgram(item.program)
    },
  }
}

function FluidInkCursor({ speed = 1, intensity = 0.55, colors, className }: FluidInkCursorProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const sessionRef = useRef<InkSession | null>(null)
  const pointerRef = useRef<number | null>(null)
  const lastRef = useRef<InkPoint | null>(null)
  const tuningRef = useRef<Tuning>({ speed, intensity, colors })
  const [blocked, setBlocked] = useState(false)
  const still = reduced || blocked

  useEffect(() => {
    tuningRef.current = { speed, intensity, colors }
  }, [speed, intensity, colors])

  useEffect(() => {
    if (reduced) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let gone = false
    let loop: GlLoopHandle | null = null
    loop = mountGlLoop(canvas, {
      host,
      frame: (frame) => {
        if (gone || !loop) return
        if (!sessionRef.current) {
          const session = startSession(loop, host, tuningRef)
          if (!session) {
            gone = true
            loop.dispose()
            setBlocked(true)
            return
          }
          sessionRef.current = session
        }
        sessionRef.current.draw(frame)
      },
    })
    if (!loop) {
      setBlocked(true)
      return () => {
        gone = true
      }
    }
    return () => {
      gone = true
      sessionRef.current?.dispose()
      sessionRef.current = null
      loop?.dispose()
    }
  }, [reduced])

  function pointOf(event: PointerEvent<HTMLDivElement>) {
    const host = hostRef.current
    if (!host) return null
    return localPoint(host, event.clientX, event.clientY)
  }

  function stir(previous: InkPoint | null, next: InkPoint) {
    const tuning = tuningRef.current
    sessionRef.current?.stir(previous, next, clampSpeed(tuning.speed), clampIntensity(tuning.intensity))
  }

  function onPointerDown(event: PointerEvent<HTMLDivElement>) {
    if (event.pointerType === "mouse" && event.button !== 0) return
    const next = pointOf(event)
    if (!next) return
    pointerRef.current = event.pointerId
    lastRef.current = next
    stir(null, next)
  }

  function onPointerMove(event: PointerEvent<HTMLDivElement>) {
    if (pointerRef.current !== event.pointerId) return
    const next = pointOf(event)
    if (!next) return
    stir(lastRef.current, next)
    lastRef.current = next
  }

  function onPointerEnd(event: PointerEvent<HTMLDivElement>) {
    if (pointerRef.current !== null && event.pointerId !== pointerRef.current) return
    pointerRef.current = null
    lastRef.current = null
  }

  return (
    <div
      ref={hostRef}
      data-slot="fluid-ink-cursor"
      data-state={still ? "still" : "live"}
      className={cn(
        "relative h-64 w-full touch-none overflow-hidden rounded-xl bg-background text-foreground select-none",
        className,
      )}
      onPointerDown={still ? undefined : onPointerDown}
      onPointerMove={still ? undefined : onPointerMove}
      onPointerUp={still ? undefined : onPointerEnd}
      onPointerLeave={still ? undefined : onPointerEnd}
      onPointerCancel={still ? undefined : onPointerEnd}
    >
      {still ? (
        <div
          data-fallback="still"
          aria-hidden
          className="absolute inset-0"
          style={{ backgroundColor: "var(--background)", backgroundImage: stillPaint(colors) }}
        />
      ) : (
        <canvas ref={canvasRef} aria-hidden className="absolute inset-0 h-full w-full" />
      )}
      <p className="pointer-events-none relative z-10 p-4 text-sm">{still ? "Ink at rest" : "Stir the ink"}</p>
    </div>
  )
}

export { FluidInkCursor }

"use client"

/** 设备像素比上限 1.5。0 或空值按 1。 */
export function cappedDpr(dpr: number): number {
  return Math.min(dpr || 1, 1.5)
}

/** 离开视口或页面隐藏时，连续帧停住。 */
export function shouldDrawFrame(inView: boolean, pageVisible: boolean): boolean {
  return inView && pageVisible
}

export type GlContext = WebGL2RenderingContext | WebGLRenderingContext

export interface GlSize {
  cssWidth: number
  cssHeight: number
  width: number
  height: number
  dpr: number
}

export interface GlFrame {
  gl: GlContext
  time: number
  dt: number
  size: GlSize
}

/** 浮点颜色附件是否可渲染。half 为真时用半精度。 */
export interface FloatSupport {
  renderable: boolean
  half: boolean
}

export interface GlTarget {
  framebuffer: WebGLFramebuffer
  texture: WebGLTexture
  width: number
  height: number
}

export interface GlPair {
  read: GlTarget
  write: GlTarget
  swap: () => void
  resize: (width: number, height: number) => void
  dispose: () => void
}

export interface GlLoopHandle {
  gl: GlContext
  floatSupport: FloatSupport
  dispose: () => void
  size: () => GlSize
  createPair: (width: number, height: number) => GlPair | null
  /** 全屏三角形。顶点属性 location 0，名字是 a。 */
  draw: () => void
}

interface TexFormat {
  internal: number
  format: number
  type: number
}

function isGlContext(value: unknown): value is GlContext {
  if (typeof value !== "object" || value === null) return false
  const record = value as { createShader?: unknown; drawArrays?: unknown; getExtension?: unknown }
  return (
    typeof record.createShader === "function" &&
    typeof record.drawArrays === "function" &&
    typeof record.getExtension === "function"
  )
}

function isWebGL2(gl: GlContext): gl is WebGL2RenderingContext {
  return typeof (gl as WebGL2RenderingContext).drawBuffers === "function"
}

function obtainGl(canvas: HTMLCanvasElement): GlContext | null {
  const attrs: WebGLContextAttributes = {
    alpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    premultipliedAlpha: false,
  }
  try {
    const gl2 = canvas.getContext("webgl2", attrs)
    if (isGlContext(gl2)) return gl2
    const gl = canvas.getContext("webgl", attrs)
    if (isGlContext(gl)) return gl
    return null
  } catch {
    return null
  }
}

function byteFormat(gl: GlContext): TexFormat {
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.UNSIGNED_BYTE }
}

function floatFormat(gl: GlContext, support: FloatSupport): TexFormat {
  if (!support.renderable) return byteFormat(gl)
  if (isWebGL2(gl)) {
    if (support.half) return { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT }
    return { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT }
  }
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }
}

function fillTexture(gl: GlContext, texture: WebGLTexture, width: number, height: number, format: TexFormat) {
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texImage2D(gl.TEXTURE_2D, 0, format.internal, width, height, 0, format.format, format.type, null)
}

function attach(gl: GlContext, framebuffer: WebGLFramebuffer, texture: WebGLTexture) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer)
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0)
  return gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE
}

function probeFormat(gl: GlContext, format: TexFormat): boolean {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return false
  }
  fillTexture(gl, texture, 1, 1, format)
  const ok = attach(gl, framebuffer, texture)
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  gl.deleteTexture(texture)
  gl.deleteFramebuffer(framebuffer)
  return ok
}

function probeFloat(gl: GlContext): FloatSupport {
  if (!isWebGL2(gl)) {
    const textureFloat = gl.getExtension("OES_texture_float")
    const colorBuffer = gl.getExtension("WEBGL_color_buffer_float")
    if (!textureFloat || !colorBuffer) return { renderable: false, half: false }
    return { renderable: probeFormat(gl, { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }), half: false }
  }
  gl.getExtension("EXT_color_buffer_float")
  if (probeFormat(gl, { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT })) {
    return { renderable: true, half: true }
  }
  if (probeFormat(gl, { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT })) {
    return { renderable: true, half: false }
  }
  return { renderable: false, half: false }
}

function destroyTarget(gl: GlContext, target: GlTarget) {
  gl.deleteFramebuffer(target.framebuffer)
  gl.deleteTexture(target.texture)
}

function createTarget(gl: GlContext, width: number, height: number, support: FloatSupport): GlTarget | null {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return null
  }
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  const preferred = floatFormat(gl, support)
  fillTexture(gl, texture, w, h, preferred)
  let ok = attach(gl, framebuffer, texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, texture, w, h, byteFormat(gl))
    ok = attach(gl, framebuffer, texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (!ok) {
    gl.deleteTexture(texture)
    gl.deleteFramebuffer(framebuffer)
    return null
  }
  return { framebuffer, texture, width: w, height: h }
}

function resizeTarget(gl: GlContext, target: GlTarget, width: number, height: number, support: FloatSupport) {
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  if (target.width === w && target.height === h) return
  const preferred = floatFormat(gl, support)
  fillTexture(gl, target.texture, w, h, preferred)
  let ok = attach(gl, target.framebuffer, target.texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, target.texture, w, h, byteFormat(gl))
    ok = attach(gl, target.framebuffer, target.texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (ok) {
    target.width = w
    target.height = h
  }
}

function createPair(gl: GlContext, width: number, height: number, support: FloatSupport): GlPair | null {
  const first = createTarget(gl, width, height, support)
  const second = createTarget(gl, width, height, support)
  if (!first || !second) {
    if (first) destroyTarget(gl, first)
    if (second) destroyTarget(gl, second)
    return null
  }
  const pair: GlPair = {
    read: first,
    write: second,
    swap() {
      const next = pair.read
      pair.read = pair.write
      pair.write = next
    },
    resize(nextWidth, nextHeight) {
      resizeTarget(gl, pair.read, nextWidth, nextHeight, support)
      resizeTarget(gl, pair.write, nextWidth, nextHeight, support)
    },
    dispose() {
      destroyTarget(gl, pair.read)
      destroyTarget(gl, pair.write)
    },
  }
  return pair
}

function measureOf(host: HTMLElement, canvas: HTMLCanvasElement): GlSize {
  const rect = host.getBoundingClientRect()
  const cssWidth = Math.max(1, rect.width || host.clientWidth || 1)
  const cssHeight = Math.max(1, rect.height || host.clientHeight || 1)
  const raw = typeof window === "undefined" ? 1 : window.devicePixelRatio
  const dpr = cappedDpr(typeof raw === "number" ? raw : 1)
  const width = Math.max(1, Math.round(cssWidth * dpr))
  const height = Math.max(1, Math.round(cssHeight * dpr))
  if (canvas.width !== width) canvas.width = width
  if (canvas.height !== height) canvas.height = height
  return { cssWidth, cssHeight, width, height, dpr }
}

function createTriangle(gl: GlContext): WebGLBuffer | null {
  const buffer = gl.createBuffer()
  if (!buffer) return null
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
  gl.bindBuffer(gl.ARRAY_BUFFER, null)
  return buffer
}

function releaseContext(gl: GlContext) {
  gl.getExtension("WEBGL_lose_context")?.loseContext()
}

/**
 * 多 pass 效果共用的原始 WebGL 循环。只管生命周期：成对 framebuffer、全屏三角形、
 * 浮点纹理探测、像素比上限、尺寸、离屏暂停、卸载时释放 context。
 * getContext 拿不到时返回 null，不抛。
 */
export function mountGlLoop(
  canvas: HTMLCanvasElement,
  options: {
    host: HTMLElement
    frame: (frame: GlFrame) => void
  },
): GlLoopHandle | null {
  const gl = obtainGl(canvas)
  if (!gl) return null
  const triangle = createTriangle(gl)
  if (!triangle) {
    releaseContext(gl)
    return null
  }
  const floatSupport = probeFloat(gl)
  let current = measureOf(options.host, canvas)
  let alive = true
  let raf = 0
  let last = 0
  let inView = true
  let pageVisible = document.visibilityState !== "hidden"
  let observer: IntersectionObserver | null = null
  const context = gl

  function poke() {
    if (!alive || raf !== 0) return
    if (!shouldDrawFrame(inView, pageVisible)) return
    raf = requestAnimationFrame(tick)
  }

  function tick(now: number) {
    raf = 0
    if (!alive || !shouldDrawFrame(inView, pageVisible)) return
    const dt = last === 0 ? 0 : Math.min(0.05, (now - last) / 1000)
    last = now
    current = measureOf(options.host, canvas)
    options.frame({ gl: context, time: now / 1000, dt, size: current })
    if (alive) poke()
  }

  function onVisibility() {
    pageVisible = document.visibilityState !== "hidden"
    poke()
  }

  if (typeof IntersectionObserver === "function") {
    inView = false
    observer = new IntersectionObserver((entries) => {
      const entry = entries[entries.length - 1]
      inView = entry ? entry.isIntersecting : true
      poke()
    })
    observer.observe(options.host)
  }
  document.addEventListener("visibilitychange", onVisibility)
  poke()

  return {
    gl,
    floatSupport,
    size: () => current,
    createPair: (width, height) => (alive ? createPair(gl, width, height, floatSupport) : null),
    draw() {
      if (!alive) return
      gl.bindBuffer(gl.ARRAY_BUFFER, triangle)
      gl.enableVertexAttribArray(0)
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    },
    dispose() {
      if (!alive) return
      alive = false
      if (raf !== 0) cancelAnimationFrame(raf)
      raf = 0
      observer?.disconnect()
      document.removeEventListener("visibilitychange", onVisibility)
      gl.bindBuffer(gl.ARRAY_BUFFER, null)
      gl.deleteBuffer(triangle)
      releaseContext(gl)
    },
  }
}

function vert(webgl2: boolean) {
  const head = webgl2 ? "#version 300 es\nin vec2 a;\nout vec2 v;\n" : "attribute vec2 a;\nvarying vec2 v;\n"
  return `${head}void main(){v=a*0.5+0.5;gl_Position=vec4(a,0.0,1.0);}`
}

function frag(webgl2: boolean, body: string) {
  const head = webgl2
    ? "#version 300 es\nprecision highp float;\nin vec2 v;\nout vec4 frag;\n#define TEX texture\n#define WRITE frag\n"
    : "precision mediump float;\nvarying vec2 v;\n#define TEX texture2D\n#define WRITE gl_FragColor\n"
  return head + body
}

export function inkVertex(webgl2: boolean) {
  return vert(webgl2)
}

export function inkSplatVelocity(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uTex;
uniform vec2 uPoint;
uniform vec2 uForce;
uniform float uRadius;
void main() {
  vec2 vel = TEX(uTex, v).xy;
  vec2 d = v - uPoint;
  float w = exp(-dot(d, d) / max(uRadius * uRadius, 1e-4));
  vel += uForce * w;
  WRITE = vec4(vel, 0.0, 1.0);
}`,
  )
}

export function inkSplatDye(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uTex;
uniform vec2 uPoint;
uniform vec3 uColor;
uniform float uAmount;
uniform float uRadius;
void main() {
  vec4 ink = TEX(uTex, v);
  vec2 d = v - uPoint;
  float w = exp(-dot(d, d) / max(uRadius * uRadius, 1e-4));
  float add = clamp(uAmount * w, 0.0, 1.0);
  WRITE = vec4(mix(ink.rgb, uColor, add), min(1.0, ink.a + add));
}`,
  )
}

export function inkAdvect(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uTex;
uniform sampler2D uVel;
uniform float uDt;
uniform float uKeep;
uniform float uDye;
void main() {
  vec2 vel = TEX(uVel, v).xy;
  vec2 prev = clamp(v - vel * uDt, vec2(0.0), vec2(1.0));
  vec4 sample = TEX(uTex, prev);
  if (uDye > 0.5) WRITE = vec4(sample.rgb, sample.a * uKeep);
  else WRITE = vec4(sample.xy * uKeep, 0.0, 1.0);
}`,
  )
}

export function inkDiverge(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uVel;
uniform vec2 uTexel;
void main() {
  float l = TEX(uVel, v - vec2(uTexel.x, 0.0)).x;
  float r = TEX(uVel, v + vec2(uTexel.x, 0.0)).x;
  float b = TEX(uVel, v - vec2(0.0, uTexel.y)).y;
  float t = TEX(uVel, v + vec2(0.0, uTexel.y)).y;
  WRITE = vec4(((r - l) + (t - b)) * 0.5, 0.0, 0.0, 1.0);
}`,
  )
}

export function inkJacobi(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uPress;
uniform sampler2D uDiv;
uniform vec2 uTexel;
void main() {
  float l = TEX(uPress, v - vec2(uTexel.x, 0.0)).x;
  float r = TEX(uPress, v + vec2(uTexel.x, 0.0)).x;
  float b = TEX(uPress, v - vec2(0.0, uTexel.y)).x;
  float t = TEX(uPress, v + vec2(0.0, uTexel.y)).x;
  float div = TEX(uDiv, v).x;
  WRITE = vec4((l + r + b + t - div) * 0.25, 0.0, 0.0, 1.0);
}`,
  )
}

export function inkProject(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uVel;
uniform sampler2D uPress;
uniform vec2 uTexel;
void main() {
  float l = TEX(uPress, v - vec2(uTexel.x, 0.0)).x;
  float r = TEX(uPress, v + vec2(uTexel.x, 0.0)).x;
  float b = TEX(uPress, v - vec2(0.0, uTexel.y)).x;
  float t = TEX(uPress, v + vec2(0.0, uTexel.y)).x;
  vec2 vel = TEX(uVel, v).xy - vec2(r - l, t - b);
  WRITE = vec4(vel, 0.0, 1.0);
}`,
  )
}

export function inkDisplay(webgl2: boolean) {
  return frag(
    webgl2,
    `uniform sampler2D uTex;
void main() {
  vec4 ink = TEX(uTex, v);
  WRITE = vec4(ink.rgb, clamp(ink.a, 0.0, 1.0));
}`,
  )
}
